def main() -> int:
    feed_url = os.environ.get("LBOXD_RSS_URL", DEFAULT_FEED_URL)
    output_path = os.environ.get("LBOXD_RSS_OUTPUT", str(DEFAULT_OUTPUT))
    try:
        result = export_activity(feed_url, output_path)
